using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Interactivity;
using Avalonia.Threading;
using Avalonia.VisualTree;
using OfficeIMO;
namespace ProjectDesk;
internal static class PdfValidation {
 public static int Run(string file,string output){Directory.CreateDirectory(output);AppBuilder.Configure<DesktopApp>().UseSkia().UseHeadless(new AvaloniaHeadlessPlatformOptions{UseHeadlessDrawing=false}).SetupWithoutStarting();using var session=new ProjectSession();session.Open(file);byte[] original=File.ReadAllBytes(file);string xml=session.Document!.ToXml(new(){LossPolicy=OfficeConversionLossPolicy.Allow});var window=new PlannerWindow(session,Path.Combine(output,"pdf-views-"+Guid.NewGuid()+".json"));window.Show();void Pump(){Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick(3);Dispatcher.UIThread.RunJobs();}Pump();int checks=0;void Assert(bool value,string message){if(!value)throw new Exception(message);checks++;}
  foreach(var content in Enum.GetValues<PdfContent>()){var options=new PdfOptions(Content:content,RowsPerPage:8,PagesWide:2,AllTasks:true);var data=ProjectPdfExporter.Capture(session,window.Sheet,window.Timeline,window.Axis,window.Formatting,options);string pdf=Path.Combine(output,content+"-"+Guid.NewGuid()+".pdf");var result=ProjectPdfExporter.Export(pdf,data,options);Assert(File.ReadAllBytes(pdf).Take(5).SequenceEqual("%PDF-"u8.ToArray()),"Not a PDF document");Assert(result.Pages>=2&&result.Tasks==session.Tasks.Count,"PDF pagination/task coverage mismatch");if(content!=PdfContent.Timelines)Assert(result.Pages==2*Math.Max(1,(int)Math.Ceiling(session.Tasks.Count/8d)),"PDF row/time pagination lost tasks");try{ProjectPdfExporter.Export(pdf,data,options);Assert(false,"Existing PDF overwritten");}catch(IOException){checks++;}Console.WriteLine($"PDF {content}: {result.Pages} pages -> {pdf}");}
  window.Sheet.SetFilter("","Milestones");Pump();var filtered=ProjectPdfExporter.Capture(session,window.Sheet,window.Timeline,window.Axis,window.Formatting,new());Assert(filtered.Tasks.All(t=>t.Milestone)&&filtered.Tasks.Length<session.Tasks.Count,"Export ignored table filter");var all=ProjectPdfExporter.Capture(session,window.Sheet,window.Timeline,window.Axis,window.Formatting,new(AllTasks:true));Assert(all.Tasks.Length==session.Tasks.Count,"All-tasks export lost filtered tasks");window.Sheet.SetFilter("","All tasks");Pump();
  var custom=new PdfOptions(Content:PdfContent.GanttOnly,Paper:PdfPaper.A3,Landscape:false,Dates:new(window.Axis.Start.Date,window.Axis.Start.Date.AddDays(7)));var snap=ProjectPdfExporter.Capture(session,window.Sheet,window.Timeline,window.Axis,window.Formatting,custom);ProjectPdfExporter.Export(Path.Combine(output,"custom-dates-"+Guid.NewGuid()+".pdf"),snap,custom);Assert(ProjectPdfExporter.Size(custom)==(842f,1191f),"A3 portrait size wrong");
  foreach(var invalid in new[]{new PdfOptions(RowsPerPage:0),new PdfOptions(PagesWide:9),new PdfOptions(MarginMm:double.NaN),new PdfOptions(Dates:new(DateTime.Today,DateTime.Today.AddDays(-1)))}){try{ProjectPdfExporter.Validate(invalid);Assert(false,"Invalid PDF options accepted");}catch(ArgumentException){checks++;}}
  // Dense timelines must paginate at a readable graphic height, rather than clipping the lower blocks.
  var basis=all.Tasks.First(t=>t.Start.HasValue&&t.Finish>t.Start);var many=Enumerable.Range(1,35).Select(i=>basis with{Uid=10000+i,Id=i,Name="Résumé item "+i,Summary=false,Milestone=false}).ToArray();var dense=all with{Name="Dense timeline",Tasks=many,Lanes=[new("Dense",many.Select(t=>t.Uid).ToArray(),new(),new(BarColor:"#FF7E52B5",TextColor:"#FFFFFFFF",ShowDates:false,RoundedBars:false),new(){[many[0].Uid]=new("Custom delivery","#FF397FD1")})]};var denseOptions=new PdfOptions(Content:PdfContent.Timelines,RowsPerPage:60);var denseResult=ProjectPdfExporter.Export(Path.Combine(output,"dense-styled-timeline-"+Guid.NewGuid()+".pdf"),dense,denseOptions);Assert(denseResult.Pages>=4,"Dense timeline clipped rows instead of adding pages");Assert(SkiaSharp.SKColor.TryParse("#FF397FD1",out var parsed)&&parsed.Red==0x39&&parsed.Green==0x7F&&parsed.Blue==0xD1&&parsed.Alpha==255,"Timeline ARGB not interpreted correctly in PDF");
  window.Formatting.Edit(session.HistoryPosition,d=>d.ChartColors["Task"]="#397FD1");var paletteSnapshot=ProjectPdfExporter.Capture(session,window.Sheet,window.Timeline,window.Axis,window.Formatting,new(),window.Gantt);Assert(paletteSnapshot.Palette?.GetValueOrDefault("Task")=="#397FD1","PDF snapshot lost chart palette");window.Formatting.Undo();
  var fit=custom with{FitOnePageTall=true,PagesWide=2};var fitResult=ProjectPdfExporter.Export(Path.Combine(output,"fit-page-"+Guid.NewGuid()+".pdf"),snap,fit);Assert(fitResult.Pages==2,"Fit to one page tall ignored");
  var dialog=new PdfExportWindow(window.Axis,0,session.Document.Name,opts=>Task.FromResult(PdfPreview.Create(snap,opts)));var completion=dialog.ShowDialog<PdfOptions?>(window);Pump();using(var frame=dialog.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"pdf-export-dialog.png"));Assert(dialog.GetVisualDescendants().OfType<ComboBox>().Any(c=>c.Name=="PdfContent"),"PDF format selector missing");dialog.GetVisualDescendants().OfType<Button>().Single(b=>Equals(b.Content,"Preview…")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();var preview=dialog.OwnedWindows.OfType<PdfPreviewWindow>().Single();Assert(preview.PageCount>=1&&preview.GetVisualDescendants().OfType<Avalonia.Controls.Image>().Single().Source!=null,"Print preview did not render actual page");using(var frame=preview.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"print-preview.png"));preview.GetVisualDescendants().OfType<Button>().Single(b=>Equals(b.Content,"Next")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));preview.Close();Pump();dialog.GetVisualDescendants().OfType<Button>().Single(b=>Equals(b.Content,"Cancel")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Assert(completion.IsCompleted&&completion.Result==null,"Cancel did not cancel PDF options");
  var setup=new PdfExportWindow(window.Axis,0,session.Document.Name);var accepted=setup.ShowDialog<PdfOptions?>(window);Pump();var tabs=setup.GetVisualDescendants().OfType<TabControl>().Single(t=>t.Name=="PdfPageSetupTabs");tabs.SelectedIndex=3;Pump();setup.GetVisualDescendants().OfType<TextBox>().Single(t=>t.Name=="PdfHeader").Text="Reviewed plan";setup.GetVisualDescendants().OfType<TextBox>().Single(t=>t.Name=="PdfFooter").Text="";tabs.SelectedIndex=1;Pump();setup.GetVisualDescendants().OfType<NumericUpDown>().Single(t=>t.Name=="PdfMargins").Value=20;setup.GetVisualDescendants().OfType<CheckBox>().Single(t=>t.Name=="PdfFitTall").IsChecked=true;tabs.SelectedIndex=2;Pump();setup.GetVisualDescendants().OfType<CheckBox>().Single(t=>t.Name=="PdfCustomDates").IsChecked=true;setup.GetVisualDescendants().OfType<CalendarDatePicker>().Single(t=>t.Name=="PdfStart").SelectedDate=window.Axis.LastDate;setup.GetVisualDescendants().OfType<CalendarDatePicker>().Single(t=>t.Name=="PdfFinish").SelectedDate=window.Axis.Start;void Apply(){setup.GetVisualDescendants().OfType<Button>().Single(b=>Equals(b.Content,"Export…")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}Apply();Assert(setup.IsVisible&&!accepted.IsCompleted,"PDF options dialog accepted invalid dates");setup.GetVisualDescendants().OfType<CalendarDatePicker>().Single(t=>t.Name=="PdfStart").SelectedDate=window.Axis.Start;setup.GetVisualDescendants().OfType<CalendarDatePicker>().Single(t=>t.Name=="PdfFinish").SelectedDate=window.Axis.LastDate;Apply();Assert(accepted.IsCompleted&&accepted.Result is {Header:"Reviewed plan",Footer:"",MarginMm:20,FitOnePageTall:true},"Page setup did not retain custom header/blank footer/margins/scaling");
  Assert(original.SequenceEqual(File.ReadAllBytes(file))&&!session.HasEdits&&session.Document.ToXml(new(){LossPolicy=OfficeConversionLossPolicy.Allow})==xml,"PDF export changed original/model");window.CloseForValidation();Console.WriteLine($"PASS: {checks} PDF checks; three modes, pagination, filters/all tasks, A3 dates, invalid options, overwrite protection, dialog cancel, unchanged source/model.");return 0;
 }
}
